#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;using System.IO;using System.Collections;using UnityEngine;
public class SallyCapture:MonoBehaviour {
 int checks;string path;void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-sally-check")<0)return;var g=new GameObject("Sally checks");DontDestroyOnLoad(g);g.AddComponent<SallyCapture>();}
 IEnumerator Start(){Application.runInBackground=true;path=Path.Combine(Application.dataPath,"../SallyChecks");Directory.CreateDirectory(path);yield return null;SaveMenu.StartCampaign(false);yield return new WaitForSecondsRealtime(2);try{Run();File.WriteAllText(Path.Combine(path,"checks.txt"),"SALLY_CHECKS "+checks+" passed");}catch(Exception e){File.WriteAllText(Path.Combine(path,"checks.txt"),e.ToString());Application.Quit(1);yield break;}var manager=FindObjectOfType<ManagerUI>();CouncilUI.For(manager).WallSpecialActions();yield return new WaitForSecondsRealtime(.5f);ScreenCapture.CaptureScreenshot(Path.Combine(path,"special-actions.png"));yield return new WaitForSecondsRealtime(.5f);Application.Quit();}
 void Run(){var state=VariableSingleton.Instance.CaptureState();state.turn=16;VariableSingleton.Instance.RestoreValidated(state);SallyOut.EnsureLightCavalry();var baseline=VariableSingleton.Instance.CaptureState();Check(DailyLifeEvents.I("iOttLightCavalry")==3000,"initial cavalry");Check(SallyOut.CutOffChance(50)==0&&SallyOut.CutOffChance(300)==6,"risk thresholds");
 for(int mission=0;mission<6;mission++)for(int seed=0;seed<100;seed++){
 VariableSingleton.Instance.RestoreValidated(baseline);VariableSingleton.SetInt("iCavalry",300);VariableSingleton.SetInt("iSallyLastDay",0);SharedProvisions.Set(SharedProvisions.City,100.25);SharedProvisions.Set(SharedProvisions.Camp,1000.75);UnityEngine.Random.InitState(seed);double food=SharedProvisions.Stock(SharedProvisions.City)+SharedProvisions.Stock(SharedProvisions.Camp);string report;Check(SallyOut.Resolve(300,mission,false,out report),"valid mission");Check(CouncilActions.Int("iCavalry")>=0&&CouncilActions.Int("iCavalry")<=300,"bounded casualties");Check(Math.Abs(food-SharedProvisions.Stock(SharedProvisions.City)-SharedProvisions.Stock(SharedProvisions.Camp))<.00001,"food conserved");Check(!SallyOut.Resolve(1,mission,false,out report),"same-day repeat blocked");var saved=VariableSingleton.Instance.CaptureState();int light=DailyLifeEvents.I("iOttLightCavalry");VariableSingleton.Instance.RestoreValidated(saved);Check(DailyLifeEvents.I("iOttLightCavalry")==light,"cavalry save roundtrip");if(mission==5)Check(!MehmedAssassination.Victory,"ordinary suicide cannot win");
 }VariableSingleton.Instance.RestoreValidated(baseline);}
}
#endif
